// Rapid lookup map for all valid slugs (including PID aliases)
export const KOCHI_PROJECTS_BY_SLUG = new Map();
export const KOCHI_ALL_SLUGS = [];
export const KOCHI_PROJECT_COORDINATES = {};

KOCHI_REGISTRY_PROJECTS.forEach((p) => {
  KOCHI_PROJECTS_BY_SLUG.set(p.slug.toLowerCase(), p);
  KOCHI_ALL_SLUGS.push(p.slug);

  // Alias with PID only
  KOCHI_PROJECTS_BY_SLUG.set(String(p.id), p);
  KOCHI_PROJECTS_BY_SLUG.set(`pid-${p.id}`, p);

  // Alias with standard name slug
  const baseNameSlug = p.name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  if (!KOCHI_PROJECTS_BY_SLUG.has(baseNameSlug)) {
    KOCHI_PROJECTS_BY_SLUG.set(baseNameSlug, p);
  }

  // Alias with reference URL slug (e.g., sobha-atlantis-vytilla-pid-11928)
  if (p.referenceUrl) {
    const urlSlug = p.referenceUrl.split("/").pop().toLowerCase();
    if (urlSlug && !KOCHI_PROJECTS_BY_SLUG.has(urlSlug)) {
      KOCHI_PROJECTS_BY_SLUG.set(urlSlug, p);
    }
  }

  // Register coordinates
  if (typeof p.lat === "number" && typeof p.lng === "number") {
    KOCHI_PROJECT_COORDINATES[p.slug] = {
      lat: p.lat,
      lng: p.lng,
      locality: p.location,
      city: "kochi",
      cityName: "Kochi",
      propertyType: p.type || "Apartment",
      verified: true
    };
    KOCHI_PROJECT_COORDINATES[p.id] = KOCHI_PROJECT_COORDINATES[p.slug];
  }
});

// Standard floor plan generator helper for dynamic detail pages
function generateFloorPlansForKochiProject(p) {
  const typologies = (p.flatTypes || "2, 3 BHK").toLowerCase();
  const plans = [];

  if (typologies.includes("1 bhk") || typologies.includes("1bhk") || typologies.includes("1,")) {
    plans.push({
      type: "1 BHK Smart Suite",
      bhk: "1 BHK",
      carpetArea: "480 - 580 sq.ft",
      superArea: "680 - 800 sq.ft",
      price: p.priceNumeric ? `₹ ${(p.priceNumeric * 0.55 / 10000000).toFixed(2)} Cr*` : "On Request",
      specs: { bedrooms: 1, bathrooms: 1, balconies: 1, parking: "1 Covered" },
      facing: "East / Garden Facing",
      description: "Efficient residential layout crafted for contemporary urban comfort, featuring an open-plan living room, modular kitchenette, and serene sit-out.",
      layoutImage: "https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=800&q=80"
    });
  }

  if (typologies.includes("2 bhk") || typologies.includes("2bhk") || typologies.includes("2,")) {
    plans.push({
      type: "2 BHK Premium",
      bhk: "2 BHK",
      carpetArea: "780 - 1,020 sq.ft",
      superArea: "1,100 - 1,420 sq.ft",
      price: p.price ? `${p.price}*` : "On Request",
      specs: { bedrooms: 2, bathrooms: 2, balconies: 2, parking: "1 Covered" },
      facing: "North-East / Vastu Compliant",
      description: "Spacious master bedroom with en-suite bathroom, ventilated living-dining area, utility balcony, and panoramic waterfront/greenery views.",
      layoutImage: "https://images.unsplash.com/photo-1600566753376-12c8ab7fb75b?auto=format&fit=crop&w=800&q=80"
    });
  }

  if (typologies.includes("3 bhk") || typologies.includes("3bhk") || typologies.includes("3,")) {
    plans.push({
      type: "3 BHK Grande",
      bhk: "3 BHK",
      carpetArea: "1,280 - 1,750 sq.ft",
      superArea: "1,780 - 2,450 sq.ft",
      price: p.priceNumeric ? `₹ ${(p.priceNumeric * 1.25 / 10000000).toFixed(2)} Cr*` : "On Request",
      specs: { bedrooms: 3, bathrooms: 3, balconies: 3, parking: "2 Covered" },
      facing: "Scenic Waterfront / Skyline Facing",
      description: "Expansive 3-bedroom luxury layout with large master suite, walk-in dresser, modular kitchen, and double balconies overlooking Kochi landscapes.",
      layoutImage: "https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=800&q=80"
    });
  }

  if (typologies.includes("4 bhk") || typologies.includes("4bhk") || typologies.includes("4,") || typologies.includes("5 bhk")) {
    plans.push({
      type: "4 BHK Royal Penthouse",
      bhk: "4 BHK",
      carpetArea: "2,200 - 3,500 sq.ft",
      superArea: "3,100 - 4,800 sq.ft",
      price: p.priceNumeric ? `₹ ${(p.priceNumeric * 1.6 / 10000000).toFixed(2)} Cr*` : "On Request",
      specs: { bedrooms: 4, bathrooms: 4, balconies: 4, parking: "3 Covered" },
      facing: "Panoramic 270° Arabian Sea / Backwater Views",
      description: "Signature penthouse residence featuring double-height ceiling deck, private family lounge, imported marble finishing, and staff quarters.",
      layoutImage: "https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=800&q=80"
    });
  }

  if (plans.length === 0) {
    plans.push({
      type: "Standard Residence",
      bhk: p.flatTypes || "2 & 3 BHK",
      carpetArea: p.carpetArea || "950 - 1,450 sq.ft",
      superArea: "1,350 - 2,050 sq.ft",
      price: p.price || "On Request",
      specs: { bedrooms: 3, bathrooms: 2, balconies: 2, parking: "1 Covered" },
      facing: "Vastu Compliant",
      description: "Optimized residential floor plan with expansive daylight windows, modular kitchen utility space, and premium branded sanitary fittings.",
      layoutImage: "https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=800&q=80"
    });
  }

  return plans;
}

// Resolver for Kochi Project Detail Pages
export function getKochiProjectBySlug(rawSlug) {
  if (!rawSlug) return null;
  const clean = String(rawSlug).toLowerCase().trim();
  const p = KOCHI_PROJECTS_BY_SLUG.get(clean);
  if (!p) return null;

  // Convert features to structured amenities array for the UI
  const amenitiesList = (p.features || ["24/7 Security", "Clubhouse", "Swimming Pool"]).map((feat) => {
    let cat = "Lifestyle";
    let icon = "Sparkles";
    const fLower = feat.toLowerCase();
    if (fLower.includes("pool") || fLower.includes("water")) { cat = "Wellness"; icon = "Waves"; }
    else if (fLower.includes("gym") || fLower.includes("fit") || fLower.includes("yoga")) { cat = "Fitness"; icon = "Activity"; }
    else if (fLower.includes("club") || fLower.includes("hall") || fLower.includes("deck")) { cat = "Lifestyle"; icon = "Building2"; }
    else if (fLower.includes("security") || fLower.includes("cctv") || fLower.includes("gate")) { cat = "Security"; icon = "ShieldCheck"; }
    else if (fLower.includes("kid") || fLower.includes("play")) { cat = "Kids"; icon = "Smile"; }
    else if (fLower.includes("garden") || fLower.includes("tree") || fLower.includes("ev")) { cat = "Eco"; icon = "Zap"; }
    else if (fLower.includes("court") || fLower.includes("sport") || fLower.includes("track") || fLower.includes("tennis")) { cat = "Sports"; icon = "Trophy"; }

    return {
      name: feat,
      category: cat,
      icon: icon
    };
  });

  // Highlights
  const highlights = [
    `Prime address in ${p.location}`,
    `Developed by Grade-A builder ${p.builder}`,
    p.rera && p.rera !== "Not Available" ? `K-RERA Registered: ${p.rera}` : "Transparent documentation and verified compliance",
    `Available Configurations: ${p.flatTypes}`,
    `Possession: ${p.possession}`,
    "Direct builder allotment with zero brokerage through AuraLiving"
  ];

  // Nearby landmarks
  const landmarks = [
    { name: `${p.locality} Junction / Transit Corridor`, distance: "0.8 km", time: "3 mins", type: "Transit" },
    { name: "Kochi Metro Station", distance: "1.5 km", time: "5 mins", type: "Transit" },
    { name: "NH 66 / Seaport-Airport Road Connector", distance: "2.0 km", time: "6 mins", type: "Road" },
    { name: "Super-Speciality Hospital", distance: "3.0 km", time: "8 mins", type: "Healthcare" },
    { name: "Reputed International School", distance: "2.2 km", time: "6 mins", type: "Education" },
    { name: "Cochin International Airport (CIAL)", distance: "18.0 km", time: "25 mins", type: "Airport" }
  ];

  // Developer info
  const developerInfo = {
    name: p.builder,
    slug: p.developerSlug,
    logo: p.builderLogo,
    experience: "25+ Years",
    projectsCount: "35+ Projects",
    established: "1998",
    description: `${p.builder} is renowned for superior engineering quality, ethical transparency, and landmark residential deliveries across Kochi and Kerala.`
  };

  // 3-4 related slugs in Kochi
  const otherKochi = KOCHI_REGISTRY_PROJECTS.filter((item) => item.slug !== p.slug);
  const relatedSlugs = otherKochi.slice(0, 4).map((item) => item.slug);

  return {
    id: p.id,
    sourceId: p.sourceId,
    slug: p.slug,
    title: p.name,
    name: p.name,
    builder: p.builder,
    developerSlug: p.developerSlug,
    developerInfo: developerInfo,
    city: "kochi",
    cityName: "Kochi",
    region: p.region,
    locality: p.locality,
    location: p.location,
    fullAddress: p.fullAddress,
    price: p.price,
    priceNumeric: p.priceNumeric,
    avgPrice: p.avgPrice,
    flatTypes: p.flatTypes,
    carpetArea: p.carpetArea,
    possession: p.possession,
    rera: p.rera,
    rera_informations: p.rera_informations,
    status: p.status,
    tag: p.tag,
    rating: p.rating,
    reviewsCount: 84,
    images: p.images,
    overview: p.description,
    highlights: highlights,
    amenities: amenitiesList,
    floorPlans: generateFloorPlansForKochiProject(p),
    landmarks: landmarks,
    lat: p.lat,
    lng: p.lng,
    relatedProjectSlugs: relatedSlugs,
    referenceUrl: p.referenceUrl
  };
}
